    public TradeOrder testCreate() throws Throwable {
    TradeOrder entity = null;

    LOGGER.info( "TradeOrderTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a TradeOrder");

    StringBuilder msg = new StringBuilder( "-- Failed to create a TradeOrder" );

    try {
        entity = service.createTradeOrder( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getTradeOrderId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a TradeOrder with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

