    /**
     * Tests getting all TradeOrders.
     *
     * @return    Collection
     */
    public List<TradeOrder> testGetAll() throws Throwable {
    LOGGER.info( "TradeOrderTest:testGetAll() - Retrieving Collection of TradeOrders:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TradeOrder : " );
    List<TradeOrder> collection  = null;

    try {
        // call the static get method on the TradeOrderService
        collection = service.getAllTradeOrder();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TradeOrder currEntity  = null;
            Iterator<TradeOrder> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTradeOrderId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

